import type { TableCellType, TableDataType } from 'components/TableComponent';

import type { DemographicGroup } from '../../../types';
import {
  extractCellValue,
  resolveDemographicGroup,
} from './resolveRowSelection';

export type DemographicGroupOptions = Record<DemographicGroup, string[]>;

const emptyOptions = (): DemographicGroupOptions => ({
  gender: [],
  age: [],
  income: [],
});

type BreakdownRow = Record<
  string,
  TableCellType | string | number | boolean | undefined
>;

export const getDemographicGroupOptions = (
  data: TableDataType | null | undefined,
): DemographicGroupOptions => {
  const options = emptyOptions();
  if (!data?.rows) return options;

  data.rows.forEach((groupRows) => {
    const rows = (groupRows ?? []) as BreakdownRow[];
    const firstRow = rows[0];
    const group = resolveDemographicGroup(
      firstRow ? extractCellValue(firstRow['rowGroupLabel']) : null,
    );
    if (!group) return;

    rows.forEach((row) => {
      const segment = extractCellValue(row['segment']);
      if (segment && !options[group].includes(segment)) {
        options[group].push(segment);
      }
    });
  });

  return options;
};
